export const title = "Can a Monitor Riser Fit a Full-Size Keyboard Underneath?";
export const metaTitle = "Can a Monitor Riser Fit a Full-Size Keyboard";
export const metaDescription = "Measure the clear bay, not shelf width. Practical measurements, original diagrams and fit checks for monitor storage in small workspaces.";
